package com.telamin.mongoose.control.validation;

import org.junit.jupiter.api.Test;

import static org.junit.jupiter.api.Assertions.*;

/** Independent malformed evidence, not traces generated by the implementation being checked. */
class ControlResourceEvidenceReviewTest {
    private static ControlInvariants.Result check(String... records) {
        StringBuilder yaml = new StringBuilder();
        for (int i = 0; i < records.length; i++) {
            yaml.append("---\neventLogRecord:\n  nodeLogs:\n    - node: {seq: ")
                    .append(i + 1).append(", ").append(records[i]).append("}\n");
        }
        return ControlInvariants.check(ControlEvidence.parse(yaml.toString(), true));
    }

    @Test void failedCloseDoesNotProveResourceClosure() {
        var result = check(
                "record: Decision, rule: captureOpened, resourceId: 41, effects: ''",
                "record: EffectOutcome, effect: CloseCapture, outcome: failed, resourceId: 41");
        assertFalse(result.verified(), result.toString());
        assertTrue(result.unverifiable().stream().anyMatch(s -> s.contains("41") && s.contains("close failed")), result.toString());
    }

    @Test void orphanOpenStillNeedsPhysicalClosure() {
        String yaml = "---\ncontrolFallback: {record: EffectOutcome, effect: OpenCapture, outcome: succeeded, resourceId: 41}\n";
        var result = ControlInvariants.check(ControlEvidence.parse(yaml, true));
        assertTrue(result.violations().stream().anyMatch(s -> s.startsWith("I4 ")), result.toString());
    }

    @Test void unknownPhysicalCloseIsNotSilentlyExcludedFromAccounting() {
        var result = check("record: EffectOutcome, effect: CloseCapture, outcome: succeeded, resourceId: 41");
        assertTrue(result.violations().stream().anyMatch(s -> s.startsWith("I11 ")), result.toString());
    }

    @Test void oneResourceCannotBelongToTwoStartedGenerations() {
        var result = check(
                "record: Decision, rule: started, generation: 7, name: p, effects: ''",
                "record: Decision, rule: started, generation: 8, name: q, effects: ''",
                "record: EffectOutcome, effect: InstallCapture, outcome: succeeded, generation: 7, resourceId: 41",
                "record: EffectOutcome, effect: InstallCapture, outcome: succeeded, generation: 8, resourceId: 41");
        assertTrue(result.violations().stream().anyMatch(s -> s.startsWith("I12 resource 41 installed again")), result.toString());
    }

    @Test void spuriousUninstallCannotCancelOutASecondInstallation() {
        var result = check(
                "record: Decision, rule: started, generation: 7, name: p, effects: ''",
                "record: EffectOutcome, effect: UninstallCapture, outcome: succeeded, generation: 7, resourceId: 41",
                "record: EffectOutcome, effect: InstallCapture, outcome: succeeded, generation: 7, resourceId: 41",
                "record: EffectOutcome, effect: InstallCapture, outcome: succeeded, generation: 7, resourceId: 42");
        assertTrue(result.violations().stream().anyMatch(s -> s.startsWith("I12 a second")), result.toString());
    }

    @Test void anOpenedResourceCannotBeInstalledOnAReplacement() {
        var result = check(
                "record: Decision, rule: started, generation: 8, name: p, effects: ''",
                "record: Decision, rule: captureOpened, generation: 7, resourceId: 41, effects: ''",
                "record: EffectOutcome, effect: InstallCapture, outcome: succeeded, generation: 8, resourceId: 41");
        assertTrue(result.violations().stream().anyMatch(s -> s.startsWith("I12 resource 41 opened for")), result.toString());
    }

    @Test void closingDecisionCannotAlsoStartWork() {
        var result = check("record: Decision, requestId: 1, rule: closeGroup, effects: '1.1 BuildAndStart(7)'");
        assertTrue(result.violations().stream().anyMatch(s -> s.startsWith("I7 ")), result.toString());
    }

    @Test void failedServiceCallbackCannotBeReportedApplied() {
        var result = check(
                "record: EffectOutcome, requestId: 1, opId: '1.1', effect: DeliverService, outcome: failed",
                "record: Reply, requestId: 1, opId: '1.2', outcome: APPLIED");
        assertTrue(result.violations().stream().anyMatch(s -> s.startsWith("I8 ")), result.toString());
    }

    @Test void lateTimedOutOpenWithANewResourceMayBeCompensated() {
        var result = check(
                "record: EffectOutcome, requestId: 1, opId: '1.1', effect: OpenCapture, outcome: failed",
                "record: EffectOutcome, requestId: 1, opId: '1.1', effect: OpenCapture, outcome: succeeded, duplicate: true, resourceId: 41",
                "record: Decision, requestId: 1, rule: captureDuplicate, resourceId: 41, effects: '1.c1 CloseCapture(-1)'",
                "record: EffectOutcome, requestId: 1, opId: '1.c1', effect: CloseCapture, outcome: succeeded, resourceId: 41");
        assertTrue(result.verified(), result.toString());
    }

    @Test void orphanCompensatingEffectNeedsAFinalOutcome() {
        String yaml = "---\ncontrolFallback: {record: EffectRequested, requestId: 1, opId: '1.orphan-close.41', effect: CloseCapture, resourceId: 41}\n";
        var result = ControlInvariants.check(ControlEvidence.parse(yaml, true));
        assertTrue(result.violations().stream().anyMatch(s -> s.startsWith("I3 ")), result.toString());
    }

    @Test void fallbackOutcomeMustFollowItsEffectRequest() {
        String yaml = "---\ncontrolFallback: {record: EffectOutcome, requestId: 1, opId: '1.orphan-close.41', effect: CloseCapture, outcome: succeeded, resourceId: 41}\n"
                + "---\ncontrolFallback: {record: EffectRequested, requestId: 1, opId: '1.orphan-close.41', effect: CloseCapture, resourceId: 41}\n";
        var result = ControlInvariants.check(ControlEvidence.parse(yaml, true));
        assertTrue(result.violations().stream().anyMatch(s -> s.startsWith("I9 ")), result.toString());
    }

    @Test void successfulOfflineDetachmentProvesTerminalResourceOwnershipWasReleased() {
        var result = check(
                "record: Decision, rule: started, generation: 7, name: p, effects: ''",
                "record: Decision, rule: captureOpened, generation: 7, resourceId: 41, effects: ''",
                "record: EffectOutcome, effect: InstallCapture, outcome: succeeded, generation: 7, resourceId: 41",
                "record: EffectOutcome, effect: UninstallCapture, outcome: succeeded, generation: -1, resourceId: 41, offline: true",
                "record: EffectOutcome, effect: CloseCapture, outcome: succeeded, resourceId: 41");
        assertTrue(result.verified(), result.toString());
    }
}
